import * as React from "react"
import { useEffect } from "react"
import L from "leaflet"
import "leaflet/dist/leaflet.css"
import "../styles/inProgress.css"

const NotFoundPage = () => {

  useEffect(() => {
    // Fix for Gatsby SSR (prevents "window is not defined")
    if (typeof window === "undefined") return

    // Prevent map from initializing multiple times
    if (document.getElementById("map")?._leaflet_id) return

    // Create map centered on Georgia Tech
    const map = L.map("map").setView([33.7765, -84.3967], 15)

    // Add map tiles
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: "&copy; OpenStreetMap contributors",
    }).addTo(map)

    // Default marker
    L.marker([33.7765, -84.3967])
      .addTo(map)
      .bindPopup("Georgia Tech")
      .openPopup()

    // Click to add new markers (your "emotion pins")
    map.on("click", function (e) {
      L.marker([e.latlng.lat, e.latlng.lng])
        .addTo(map)
        .bindPopup("New Emotion Here")
        .openPopup()
    })

  }, [])

  return (
    <main className="pageStyles">
      <h1 className="headingStyles">Buzzing Emotions</h1>
      <div id="map" className="mapContainer"></div>
    </main>
  )
}

export default NotFoundPage